-- V2 only. All fixtures, role bindings, approval records and offering changes roll back.
begin;
do $$
declare actor uuid; actor_email text; second_id uuid; org uuid; brand_rev integer; plan uuid:=gen_random_uuid(); rid uuid:=gen_random_uuid(); d jsonb; p jsonb; w jsonb; v jsonb; cfg jsonb; blocked boolean; qa_org uuid:=gen_random_uuid(); other_id uuid:=gen_random_uuid(); plan2 uuid:=gen_random_uuid(); rid2 uuid:=gen_random_uuid();
begin
 select user_id,email into actor,actor_email from public.platform_principals where email='johan.ras@apginc.ca' and public.v2_is_platform_principal(user_id);
 if actor is null then raise exception 'No principal fixture';end if;
 select id into second_id from auth.users where lower(email)='jorrie.jordaan@apginc.ca';
 if second_id is null then second_id=gen_random_uuid();insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data,raw_app_meta_data) values(second_id,'jorrie.jordaan@apginc.ca',now(),'{}','{}');end if;
 insert into public.user_roles(user_id,role) values(second_id,'admin') on conflict do nothing;
 select id,brand_revision into org,brand_rev from public.organisations where slug='apgi';
 cfg='{"hosting_fixed":"1.00","hosting_rate":"0","stripe_fixed":"0.30","stripe_rate":"2.90","administration_rate":"6","contingency_rate":"10","development_status":"recover","development_cost":"1000","already_paid":"0","recovery_rate":"25","apgi_share":"100","minimum_apgi_income":"10"}'::jsonb;
 insert into public.commercial_agreement_drafts(id,organisation_id,course_id,title,kind,configuration,created_by) values(plan,org,'vpshr-level-0','QA rollback-only continuous plan','course_agreement',cfg,actor);
 w=jsonb_build_object('version',2,'stage','content_review','ownerId',org,'partner',false,'partnerEmail','','commercials','[]'::jsonb,'counterOffers',0);
 d=jsonb_build_object('workflow',w,'title','QA rollback-only course','brand',jsonb_build_object('name','APGI','revision',brand_rev),'requester',actor_email,'requesterId',actor,'cutoff',now()+interval '7 days','units',jsonb_build_array(jsonb_build_object('slug','lu1','title','Unit 1')),'participants',jsonb_build_array(jsonb_build_object('email',actor_email,'role','primary','state','active','userId',actor,'coverage',jsonb_build_array('lu1')),jsonb_build_object('email','second@qa.invalid','role','primary','state','active','userId',other_id,'coverage',jsonb_build_array('lu1'))),'reports','[]'::jsonb,'findings','[]'::jsonb,'events','[]'::jsonb,'terms',jsonb_build_object('partner',false));
 p=jsonb_build_object('id',rid,'plan_id',null,'organisation_id',org,'course_id','vpshr-level-0','fingerprint',repeat('a',64),'document',d);
 perform public.v2_create_course_review(p,actor,'[]','[]');
 blocked=false;begin perform public.v2_create_course_review(p,actor,'[]','[]');exception when others then blocked=true;end;if not blocked then raise exception 'Duplicate review accepted';end if;
 blocked=false;begin perform public.v2_publish_reviewed_course(rid,1,actor,repeat('a',64));exception when others then blocked=true;end;if not blocked then raise exception 'Incomplete content published';end if;
 d=jsonb_set(d,'{participants,0,state}','"finished"');d=jsonb_set(d,'{participants,1,state}','"finished"');
 d=jsonb_set(d,'{reports}',jsonb_build_array(jsonb_build_object('id','r1','email',actor_email,'userId',actor,'coverage',jsonb_build_array('lu1'),'endorsements',jsonb_build_array(jsonb_build_object('email','second@qa.invalid','userId',other_id,'decision','approve'))),jsonb_build_object('id','r2','email','second@qa.invalid','userId',other_id,'coverage',jsonb_build_array('lu1'),'endorsements',jsonb_build_array(jsonb_build_object('email',actor_email,'userId',actor,'decision','approve')))));
 w=w||jsonb_build_object('stage','ready_to_publish','internalBrandRevision',brand_rev,'contentApproval',jsonb_build_object('fingerprint',repeat('a',64),'userId',actor));
 v=jsonb_build_object('id',gen_random_uuid(),'planId',plan,'submittedAt',now(),'configuration',cfg,'floor',2000,'proposedPrice',10000,'decisions',jsonb_build_array(jsonb_build_object('email',actor_email,'userId',actor,'decision','approve')));
 w=jsonb_set(w,'{commercials}',jsonb_build_array(v));d=jsonb_set(d,'{workflow}',w);
 perform public.v2_commit_course_review(rid,1,d,actor,'qa_one_decision','[]');
 blocked=false;begin perform public.v2_publish_reviewed_course(rid,2,actor,repeat('a',64));exception when others then blocked=true;end;if not blocked then raise exception 'Single principal published';end if;
 v=jsonb_set(v,'{decisions}',(v->'decisions')||jsonb_build_array(jsonb_build_object('email','jorrie.jordaan@apginc.ca','userId',second_id,'decision','approve')));w=jsonb_set(w,'{commercials}',jsonb_build_array(v));d=jsonb_set(d,'{workflow}',w);
 perform public.v2_commit_course_review(rid,2,d,actor,'qa_two_decisions','[]');
 blocked=false;begin perform public.v2_commit_course_review(rid,2,d,actor,'qa_stale','[]');exception when others then blocked=true;end;if not blocked then raise exception 'Stale write accepted';end if;
 blocked=false;begin perform public.v2_publish_reviewed_course(rid,3,actor,repeat('b',64));exception when others then blocked=true;end;if not blocked then raise exception 'Changed content published';end if;
 update public.organisations set brand_revision=brand_revision+1 where id=org;
 blocked=false;begin perform public.v2_publish_reviewed_course(rid,3,actor,repeat('a',64));exception when others then blocked=true;end;if not blocked then raise exception 'Stale brand published';end if;
 update public.organisations set brand_revision=brand_rev where id=org;
 d=jsonb_set(d,'{findings}','[{"blocking":true,"status":"open"}]');perform public.v2_commit_course_review(rid,3,d,actor,'qa_defect','[]');
 blocked=false;begin perform public.v2_publish_reviewed_course(rid,4,actor,repeat('a',64));exception when others then blocked=true;end;if not blocked then raise exception 'Blocking defect published';end if;
 d=jsonb_set(d,'{findings}','[]');d=jsonb_set(d,'{workflow,commercials,0,proposedPrice}','1');perform public.v2_commit_course_review(rid,4,d,actor,'qa_bad_price','[]');
 blocked=false;begin perform public.v2_publish_reviewed_course(rid,5,actor,repeat('a',64));exception when others then blocked=true;end;if not blocked then raise exception 'Below-floor fee published';end if;
 d=jsonb_set(d,'{workflow,commercials,0,proposedPrice}','10000');perform public.v2_commit_course_review(rid,5,d,actor,'qa_price_fixed','[]');
 perform public.v2_publish_reviewed_course(rid,6,actor,repeat('a',64));
 if not exists(select 1 from public.course_review_mail where round_id=rid and kind='published') then raise exception 'Publication email not atomic';end if;
 if not exists(select 1 from public.organisation_offerings where organisation_id=org and course_id='vpshr-level-0' and reviewed_release_id=rid and status='published') then raise exception 'Atomic publication missing';end if;
 insert into public.organisations(id,name,slug) values(qa_org,'QA rollback-only company','qa-'||qa_org);
 blocked=false;begin insert into public.organisation_offerings(organisation_id,course_id,status,created_by) values(qa_org,'vpshr-level-0','published',actor);exception when others then blocked=true;end;if not blocked then raise exception 'Direct bypass accepted';end if;
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data,raw_app_meta_data) values(other_id,'partner-'||other_id||'@qa.invalid',now(),'{}','{}');
 insert into public.organisation_memberships(organisation_id,user_id,membership_role,is_active) values(qa_org,other_id,'owner',true);
 cfg=jsonb_set(cfg,'{apgi_share}','"20"');
 insert into public.commercial_agreement_drafts(id,organisation_id,course_id,title,kind,configuration,created_by) values(plan2,qa_org,'vpshr-level-0','QA rollback-only partner plan','course_agreement',cfg,actor);
 v=jsonb_set(v,'{planId}',to_jsonb(plan2));v=jsonb_set(v,'{configuration}',cfg);v=jsonb_set(v,'{offeredAt}',to_jsonb(now()));v=jsonb_set(v,'{proposedPrice}','50000');
 w=jsonb_set(w,'{partner}','true');w=jsonb_set(w,'{partnerEmail}',to_jsonb('partner-'||other_id||'@qa.invalid'));w=jsonb_set(w,'{commercials}',jsonb_build_array(v));
 d=jsonb_set(d,'{workflow}',w);d=jsonb_set(d,'{findings}','[]');
 insert into public.course_review_rounds(id,plan_id,organisation_id,course_id,fingerprint,document) values(rid2,plan2,qa_org,'vpshr-level-0',repeat('a',64),d);
 blocked=false;begin perform public.v2_publish_reviewed_course(rid2,1,actor,repeat('a',64));exception when others then blocked=true;end;if not blocked then raise exception 'Unaccepted partner offer published';end if;
 d=jsonb_set(d,'{workflow,commercials,0,acceptance}',jsonb_build_object('email','partner-'||other_id||'@qa.invalid','userId',other_id,'price',50000,'brandRevision',0,'contentFingerprint',repeat('a',64)));
 perform public.v2_commit_course_review(rid2,1,d,actor,'qa_partner_bad_brand','[]');
 blocked=false;begin perform public.v2_publish_reviewed_course(rid2,2,actor,repeat('a',64));exception when others then blocked=true;end;if not blocked then raise exception 'Partner outdated brand accepted';end if;
 select brand_revision into brand_rev from public.organisations where id=qa_org;
 d=jsonb_set(d,'{workflow,commercials,0,acceptance,brandRevision}',to_jsonb(brand_rev));perform public.v2_commit_course_review(rid2,2,d,actor,'qa_partner_current_brand','[]');
 update public.organisation_memberships set is_active=false where organisation_id=qa_org and user_id=other_id;
 blocked=false;begin perform public.v2_publish_reviewed_course(rid2,3,actor,repeat('a',64));exception when others then blocked=true;end;if not blocked then raise exception 'Revoked company owner published';end if;
 update public.organisation_memberships set is_active=true where organisation_id=qa_org and user_id=other_id;
 blocked=false;begin
  perform public.v2_commit_course_review(rid2,3,jsonb_set(d,'{workflow,counterOffers}','3'),actor,'qa_limit','[]');
  perform public.v2_commit_course_review(rid2,4,jsonb_set(d,'{workflow,counterOffers}','0'),actor,'qa_reset','[]');
 exception when others then blocked=true;end;if not blocked then raise exception 'Counter-offer limit reset';end if;
 blocked=false;begin
  perform public.v2_commit_course_review(rid2,3,jsonb_set(d,'{workflow,stage}','"unresolved"'),actor,'qa_unresolved','[]');
  perform public.v2_commit_course_review(rid2,4,d,actor,'qa_silent_reopen','[]');
 exception when others then blocked=true;end;if not blocked then raise exception 'Unresolved negotiation reopened';end if;
 perform public.v2_publish_reviewed_course(rid2,3,actor,repeat('a',64));
 if not exists(select 1 from public.organisation_offerings where organisation_id=qa_org and reviewed_release_id=rid2 and status='published') then raise exception 'Partner approved release missing';end if;
end $$;
select 'PASS: content-first creation, duplicate protection, dual principal decisions, stale-write protection, content/branding version gates, unresolved defects, price floor, scoped partner acceptance, owner revocation, counter-offer limits and atomic explicit publication. All QA fixtures rolled back.' as verification;
rollback;
